import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.DBSoX6Zw.js";const p=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md"}'),r={name:"guide/configuration.md"};function i(c,t,n,s,l,h){return d(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>Plik is configured via a TOML file (<code>plikd.cfg</code>) and optional environment variable overrides.</p><h2 id="config-file-locations" tabindex="-1">Config File Locations <a class="header-anchor" href="#config-file-locations" aria-label="Permalink to &quot;Config File Locations&quot;">​</a></h2><p>The server looks for configuration in this order:</p><ol><li><code>--config</code> flag</li><li><code>PLIKD_CONFIG</code> environment variable</li><li><code>./plikd.cfg</code> (current directory)</li><li><code>/etc/plikd.cfg</code></li></ol><h2 id="environment-variable-override" tabindex="-1">Environment Variable Override <a class="header-anchor" href="#environment-variable-override" aria-label="Permalink to &quot;Environment Variable Override&quot;">​</a></h2><p>Any config parameter can be set via environment variable using <code>PLIKD_</code> prefix with SCREAMING_SNAKE_CASE:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PLIKD_DEBUG_REQUESTS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ./plikd</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PLIKD_LISTEN_PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">9090</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ./plikd</span></span></code></pre></div><p>Arrays and maps must be provided in JSON format. Arrays are overridden, maps are merged:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PLIKD_DATA_BACKEND_CONFIG</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;{&quot;Directory&quot;:&quot;/var/files&quot;}&#39;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ./plikd</span></span></code></pre></div><h2 id="server-settings" tabindex="-1">Server Settings <a class="header-anchor" href="#server-settings" aria-label="Permalink to &quot;Server Settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>ListenPort</code></td><td><code>8080</code></td><td>HTTP server port</td></tr><tr><td><code>ListenAddress</code></td><td><code>0.0.0.0</code></td><td>HTTP server bind address</td></tr><tr><td><code>MetricsPort</code></td><td><code>0</code></td><td>Prometheus metrics port (0 = disabled)</td></tr><tr><td><code>Path</code></td><td><code>&quot;&quot;</code></td><td>HTTP root path prefix</td></tr><tr><td><code>SslEnabled</code></td><td><code>false</code></td><td>Enable TLS</td></tr><tr><td><code>SslCert</code> / <code>SslKey</code></td><td>—</td><td>TLS certificate and key paths</td></tr><tr><td><code>TlsVersion</code></td><td><code>tlsv10</code></td><td>Minimum TLS version</td></tr><tr><td><code>NoWebInterface</code></td><td><code>false</code></td><td>Disable web UI</td></tr><tr><td><code>PlikDomain</code></td><td><code>&quot;&quot;</code></td><td>Public webapp URL (e.g., <code>https://plik.example.com</code>). Used for OAuth redirects and CORS. Does <strong>not</strong> restrict downloads on its own — set <code>DownloadDomain</code> for that</td></tr><tr><td><code>DownloadDomain</code></td><td><code>&quot;&quot;</code></td><td>Enforce download domain (e.g., <code>https://dl.plik.example.com</code>). UI/API blocking and CORS require <code>PlikDomain</code> too</td></tr><tr><td><code>DownloadDomainAlias</code></td><td><code>[]</code></td><td>Additional accepted download hosts</td></tr><tr><td><code>EnhancedWebSecurity</code></td><td><code>false</code></td><td>Extra security headers + secure cookies</td></tr><tr><td><code>SessionTimeout</code></td><td><code>365d</code></td><td>Authentication session duration</td></tr><tr><td><code>AbuseContact</code></td><td><code>&quot;&quot;</code></td><td>Abuse contact email shown in footer. <code>settings.json</code> <code>&quot;footer&quot;</code> takes precedence when set</td></tr><tr><td><code>WebappDirectory</code></td><td><code>../webapp/dist</code></td><td>Web UI static files directory</td></tr><tr><td><code>ClientsDirectory</code></td><td><code>../clients</code></td><td>CLI client binaries directory</td></tr><tr><td><code>ChangelogDirectory</code></td><td><code>../changelog</code></td><td>Release changelog directory</td></tr><tr><td><code>SourceIpHeader</code></td><td><code>&quot;&quot;</code></td><td>Header for real IP behind proxy (e.g., <code>X-Forwarded-For</code>)</td></tr><tr><td><code>UploadWhitelist</code></td><td><code>[]</code></td><td>Restrict uploads to IP ranges (CIDR)</td></tr><tr><td><code>EnableArchiveCompression</code></td><td><code>true</code></td><td>Enable zip compression for archive downloads. Set to <code>false</code> to use <code>zip.Store</code> (no compression) to prevent CPU exhaustion on public instances. See <a href="/plik/guide/security.html#archive-compression">Security — Archive Compression</a></td></tr></tbody></table><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>MaxFileSizeStr</code></td><td><code>10GB</code></td><td>Maximum file size (or <code>&quot;unlimited&quot;</code>)</td></tr><tr><td><code>MaxUserSizeStr</code></td><td><code>unlimited</code></td><td>Default per-user storage limit</td></tr><tr><td><code>MaxFilePerUpload</code></td><td><code>1000</code></td><td>Max files per upload</td></tr><tr><td><code>DefaultTTLStr</code></td><td><code>30d</code></td><td>Default time-to-live</td></tr><tr><td><code>MaxTTLStr</code></td><td><code>30d</code></td><td>Maximum TTL (0 = no limit)</td></tr></tbody></table><h2 id="feature-flags" tabindex="-1">Feature Flags <a class="header-anchor" href="#feature-flags" aria-label="Permalink to &quot;Feature Flags&quot;">​</a></h2><p>Features can be set to one of four states:</p><table tabindex="0"><thead><tr><th>Value</th><th>Behavior</th></tr></thead><tbody><tr><td><code>disabled</code></td><td>Feature always off</td></tr><tr><td><code>enabled</code></td><td>Feature available, opt-in</td></tr><tr><td><code>default</code></td><td>Feature available, opt-out (on by default)</td></tr><tr><td><code>forced</code></td><td>Feature always on</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Flag</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>FeatureAuthentication</code></td><td><code>disabled</code></td><td>User authentication (<code>forced</code> = no anonymous uploads)</td></tr><tr><td><code>FeatureOneShot</code></td><td><code>enabled</code></td><td>Files deleted after first download</td></tr><tr><td><code>FeatureRemovable</code></td><td><code>enabled</code></td><td>Anyone can delete files</td></tr><tr><td><code>FeatureStream</code></td><td><code>enabled</code></td><td>Direct uploader-to-downloader streaming</td></tr><tr><td><code>StreamTimeoutStr</code></td><td><code>5m</code></td><td>Max wait for a streaming download to start before releasing the upload goroutine (<code>0</code> = no timeout)</td></tr><tr><td><code>FeaturePassword</code></td><td><code>enabled</code></td><td>Password-protected uploads</td></tr><tr><td><code>FeatureComments</code></td><td><code>enabled</code></td><td>Markdown comments on uploads</td></tr><tr><td><code>FeatureSetTTL</code></td><td><code>enabled</code></td><td>Custom TTL setting</td></tr><tr><td><code>FeatureExtendTTL</code></td><td><code>disabled</code></td><td>Extend TTL on each download</td></tr><tr><td><code>FeatureClients</code></td><td><code>enabled</code></td><td>Show CLI download button in UI</td></tr><tr><td><code>FeatureGithub</code></td><td><code>enabled</code></td><td>Show source code link in UI</td></tr><tr><td><code>FeatureText</code></td><td><code>enabled</code></td><td>Text upload dialog</td></tr><tr><td><code>FeatureLocalLogin</code></td><td><code>enabled</code></td><td>Local login form (enable/disable only)</td></tr><tr><td><code>FeatureDeleteAccount</code></td><td><code>enabled</code></td><td>Allow users to delete their own account (enable/disable only)</td></tr></tbody></table><h2 id="full-example" tabindex="-1">Full Example <a class="header-anchor" href="#full-example" aria-label="Permalink to &quot;Full Example&quot;">​</a></h2><p>See the <a href="https://github.com/root-gg/plik/blob/master/server/plikd.cfg" target="_blank" rel="noreferrer">default plikd.cfg</a> for a fully commented configuration file.</p>`,20)])])}const b=e(r,[["render",i]]);export{p as __pageData,b as default};
